mkdir -p /app/output && python3 << 'PYEOF'
import pandas as pd
import numpy as np
import json

df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'])
df = df.sort_values('Date').reset_index(drop=True)
df['daily_ret'] = df['Close'].pct_change()
df['roll_vol_252'] = df['daily_ret'].rolling(252).std() * np.sqrt(252) * 100
rolling_max = df['Close'].cummax()
df['drawdown'] = (df['Close'] - rolling_max) / rolling_max * 100

# Monthly close for main price chart
monthly = df.set_index('Date').resample('ME').last().reset_index()
monthly_vol = df.set_index('Date').resample('ME')['Volume'].mean().reset_index()

# Prepare JSON datasets for Chart.js
price_dates = monthly['Date'].dt.strftime('%Y-%m-%d').tolist()
price_closes = monthly['Close'].round(2).tolist()

# Rolling vol (monthly last)
df_vol = df[['Date','roll_vol_252']].dropna()
vol_monthly = df_vol.set_index('Date').resample('ME').last().reset_index()
vol_dates = vol_monthly['Date'].dt.strftime('%Y-%m-%d').tolist()
vol_vals = vol_monthly['roll_vol_252'].round(2).tolist()

# Drawdown monthly
dd_monthly = df[['Date','drawdown']].set_index('Date').resample('ME').last().reset_index()
dd_dates = dd_monthly['Date'].dt.strftime('%Y-%m-%d').tolist()
dd_vals = dd_monthly['drawdown'].round(2).tolist()

# Volume monthly (in millions)
vol_m_dates = monthly_vol['Date'].dt.strftime('%Y-%m-%d').tolist()
vol_m_vals = (monthly_vol['Volume'] / 1e6).round(2).tolist()

# Annual returns
df['Year'] = df['Date'].dt.year
annual = df.groupby('Year')['Close'].agg(['first','last'])
annual['ret'] = ((annual['last'] / annual['first']) - 1) * 100
ann_years = annual.index.tolist()
ann_rets = annual['ret'].round(1).tolist()
ann_colors = ['#10b981' if r >= 0 else '#ef4444' for r in ann_rets]

# KPIs
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
cumret = (last_close / first_close - 1) * 100
years_n = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
cagr = ((last_close / first_close) ** (1/years_n) - 1) * 100
max_dd = df['drawdown'].min()
ann_vol = df['daily_ret'].std() * np.sqrt(252) * 100
avg_volume = df['Volume'].mean()
ath = df['Close'].max()
ath_date = df.loc[df['Close'].idxmax(), 'Date'].strftime('%b %d, %Y')
atl = df['Close'].min()
atl_date = df.loc[df['Close'].idxmin(), 'Date'].strftime('%b %d, %Y')

data_json = json.dumps({
    'price_dates': price_dates,
    'price_closes': price_closes,
    'vol_dates': vol_dates,
    'vol_vals': vol_vals,
    'dd_dates': dd_dates,
    'dd_vals': dd_vals,
    'vol_m_dates': vol_m_dates,
    'vol_m_vals': vol_m_vals,
    'ann_years': ann_years,
    'ann_rets': ann_rets,
    'ann_colors': ann_colors,
})

