const DATA = {data_json};

Chart.defaults.color = '#8b92b3';
Chart.defaults.borderColor = '#2d3149';
Chart.defaults.font.family = "'Inter', -apple-system, sans-serif";

const tooltipPlugin = {{
  enabled: true,
  backgroundColor: '#1a1d27',
  borderColor: '#2d3149',
  borderWidth: 1,
  titleColor: '#e8eaf0',
  bodyColor: '#8b92b3',
