// ── PRICE CHART ──────────────────────────────────────────────────────────────
const priceCtx = document.getElementById('priceChart').getContext('2d');
new Chart(priceCtx, {{
  type: 'line',
  data: {{
    labels: DATA.price_dates,
    datasets: [{{
      label: 'NKE Close (USD)',
      data: DATA.price_closes,
      borderColor: '#4f7cff',
      backgroundColor: 'rgba(79,124,255,0.08)',
      fill: true,
      borderWidth: 1.8,
      pointRadius: 0,
      tension: 0.3,
    }}]
  }},
  options: {{
    responsive: true,
    maintainAspectRatio: false,
    interaction: {{ mode: 'index', intersect: false }},
    plugins: {{
      legend: {{ display: false }},
      tooltip: {{ ...tooltipPlugin, callbacks: {{ label: ctx => ` ${{ctx.parsed.y.toFixed(2)}}` }} }},
    }},
    scales: {{
      x: {{
        type: 'time',
        time: {{ unit: 'year', displayFormats: {{ year: 'yyyy' }} }},
        grid: {{ color: '#2d3149' }},
        ticks: {{ maxTicksLimit: 14 }}
      }},
      y: {{
        type: 'logarithmic',
        grid: {{ color: '#2d3149' }},
        ticks: {{ callback: v => '$' + v }},
        title: {{ display: true, text: 'Price (USD, log scale)', color: '#8b92b3', font: {{ size: 11 }} }}
      }}
    }}
  }}
}});

// ── DRAWDOWN CHART ───────────────────────────────────────────────────────────
const ddCtx = document.getElementById('drawdownChart').getContext('2d');
new Chart(ddCtx, {{
  type: 'line',
  data: {{
    labels: DATA.dd_dates,
    datasets: [{{
      label: 'Drawdown (%)',
      data: DATA.dd_vals,
      borderColor: '#ef4444',
      backgroundColor: 'rgba(239,68,68,0.12)',
      fill: true,
      borderWidth: 1.5,
      pointRadius: 0,
      tension: 0.2,
    }}]
  }},
